import { test, expect } from '@playwright/test';

test.describe('Form Validation - Submit Button Disabled Until Required Fields Filled', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <form id="testForm">
        <div>
          <label for="firstName">First Name *</label>
          <input type="text" id="firstName" name="firstName" required />
        </div>
        <div>
          <label for="lastName">Last Name *</label>
          <input type="text" id="lastName" name="lastName" required />
        </div>
        <div>
          <label for="email">Email *</label>
          <input type="email" id="email" name="email" required />
        </div>
        <div>
          <label for="phone">Phone (Optional)</label>
          <input type="tel" id="phone" name="phone" />
        </div>
        <button type="submit" id="submitBtn">Submit</button>
      </form>
      <script>
        const form = document.getElementById('testForm');
        const submitBtn = document.getElementById('submitBtn');
        const requiredFields = form.querySelectorAll('[required]');

        function updateSubmitButtonState() {
          const allRequiredFilled = Array.from(requiredFields).every(field => field.value.trim() !== '');
          submitBtn.disabled = !allRequiredFilled;
        }

        requiredFields.forEach(field => {
          field.addEventListener('input', updateSubmitButtonState);
        });

        updateSubmitButtonState();
      </script>
    `);
  });

  test('submit button should be disabled when form loads with empty required fields', async ({ page }) => {
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await expect(submitButton).toBeDisabled();
  });

  test('submit button should remain disabled when only some required fields are filled', async ({ page }) => {
    const firstNameInput = page.getByLabel('First Name *');
    const submitButton = page.getByRole('button', { name: 'Submit' });

    await firstNameInput.fill('John');
    await expect(submitButton).toBeDisabled();

    const lastNameInput = page.getByLabel('Last Name *');
    await lastNameInput.fill('Doe');
    await expect(submitButton).toBeDisabled();
  });

  test('submit button should be enabled when all required fields are filled', async ({ page }) => {
    const firstNameInput = page.getByLabel('First Name *');
    const lastNameInput = page.getByLabel('Last Name *');
    const emailInput = page.getByLabel('Email *');
    const submitButton = page.getByRole('button', { name: 'Submit' });

    await firstNameInput.fill('John');
    await lastNameInput.fill('Doe');
    await emailInput.fill('john.doe@example.com');

    await expect(submitButton).toBeEnabled();
  });

  test('submit button should be disabled again when a required field is cleared', async ({ page }) => {
    const firstNameInput = page.getByLabel('First Name *');
    const lastNameInput = page.getByLabel('Last Name *');
    const emailInput = page.getByLabel('Email *');
    const submitButton = page.getByRole('button', { name: 'Submit' });

    await firstNameInput.fill('John');
    await lastNameInput.fill('Doe');
    await emailInput.fill('john.doe@example.com');
    await expect(submitButton).toBeEnabled();

    await firstNameInput.clear();
    await expect(submitButton).toBeDisabled();
  });

  test('optional fields should not affect submit button state', async ({ page }) => {
    const firstNameInput = page.getByLabel('First Name *');
    const lastNameInput = page.getByLabel('Last Name *');
    const emailInput = page.getByLabel('Email *');
    const phoneInput = page.getByLabel('Phone (Optional)');
    const submitButton = page.getByRole('button', { name: 'Submit' });

    await firstNameInput.fill('John');
    await lastNameInput.fill('Doe');
    await emailInput.fill('john.doe@example.com');
    await expect(submitButton).toBeEnabled();

    await phoneInput.fill('555-1234');
    await expect(submitButton).toBeEnabled();

    await phoneInput.clear();
    await expect(submitButton).toBeEnabled();
  });

  test('submit button should be clickable only when all required fields are filled', async ({ page }) => {
    const firstNameInput = page.getByLabel('First Name *');
    const lastNameInput = page.getByLabel('Last Name *');
    const emailInput = page.getByLabel('Email *');
    const submitButton = page.getByRole('button', { name: 'Submit' });

    await firstNameInput.fill('John');
    await lastNameInput.fill('Doe');

    await expect(submitButton).toBeDisabled();

    await emailInput.fill('john.doe@example.com');
    await expect(submitButton).toBeEnabled();

    await submitButton.click();
    await expect(submitButton).toBeEnabled();
  });
});
